#!/usr/bin/env python3
import json
from pathlib import Path
P=Path(__file__).resolve().parent;O=P/'out/native'
rows=[]
for code,name,trade in [('A','Typst','Composición con stack/grid; fuente declarativa y PDF etiquetado.'),('B','Beamer / LuaLaTeX','Columnas, párrafos y gráficos TikZ; fuente .tex.'),('C','HTML / Chromium','CSS Grid/Flex; aprovecha el flujo HTML actual sin rasterizar.'),('D','Scribus','Marcos editables, estilos y fondo maestro; fuente .sla.')]:
 r=json.loads((O/f'{code}.receipt.json').read_text());rows.append(f'<tr><td>{code}</td><td>{name}</td><td>{r["seconds"]} s</td><td>{(O/f"{code}.pdf").stat().st_size/1024:.0f} KiB</td><td>{trade}</td></tr>')
text='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Educación III · comparación nativa</title><style>
*{box-sizing:border-box}body{margin:0;padding:24px;background:#11151c;color:#edf0f5;font:17px/1.5 system-ui}h1{font-size:30px;margin:0}p{max-width:1000px;color:#bfc8d4}a{color:#64d8e9}nav{display:flex;gap:18px;flex-wrap:wrap;margin:18px 0}button,select,textarea{font:inherit;background:#202733;color:#edf0f5;border:1px solid #65738a;border-radius:6px;padding:8px}label{margin-right:12px}.gallery{display:grid;grid-template-columns:repeat(4,minmax(280px,390px));gap:16px;overflow-x:auto;margin:24px 0}.card{margin:0}.card h2{margin:0 0 10px;font-size:22px}.card img{width:100%;height:auto;display:block}.card a{display:block}details{margin-top:24px;border-top:1px solid #424953;padding-top:18px}table{border-collapse:collapse;width:100%;max-width:1300px}td,th{text-align:left;padding:12px;border-bottom:1px solid #424953}textarea{display:block;width:min(100%,900px);height:110px;margin:14px 0}.status{color:#a79cff}small{color:#bfc8d4}@media(max-width:700px){body{padding:16px}.gallery{grid-template-columns:repeat(4,320px)}table{font-size:14px}}
</style><h1>Educación III · segunda ronda</h1><p>Cuatro composiciones nativas, el mismo contenido. Revisa primero legibilidad, jerarquía, espacio y gráficos; después revela los motores. La calidad editorial queda a tu evaluación: no se asignó un ganador.</p><p class="status">La primera ronda fue rechazada por similitud y problemas de diagramación. Estos archivos la reemplazan para la comparación.</p>
<nav><label for="slide">Página <select id="slide">'''+''.join(f'<option value="{i}">{i:02d} / 09</option>' for i in range(1,10))+'''</select></label><button id="prev">← Anterior</button><button id="next">Siguiente →</button></nav><main class="gallery">'''
for code in 'ABCD':text+=f'<figure class="card"><h2>Propuesta {code}</h2><a href="{code}.pdf" target="_blank" rel="noopener">Abrir PDF {code}</a><a class="full" href="previews/{code}/page-1.png" target="_blank" rel="noopener"><img data-code="{code}" src="previews/{code}/page-1-390.png" alt="Propuesta {code}, página 1"></a></figure>'
text+='''</main><label for="notes">Notas de revisión — indica propuesta, página y observación</label><textarea id="notes" placeholder="Ejemplo: C, página 4: las cifras se distinguen mejor…"></textarea><button id="save">Descargar notas</button><small> Las notas se guardan en este navegador cuando permite almacenamiento local; no se envían.</small>
<details><summary>Revelar motores y mediciones</summary><table><thead><tr><th>Propuesta</th><th>Motor</th><th>Generación local</th><th>PDF</th><th>Implementación</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table><p>Una ejecución por motor; tiempos incluyen arranque, con cachés locales. No miden costo de edición humana ni constituyen un benchmark general.</p><p>Las cuatro superan los controles de contenido, 9 páginas, fuentes incrustadas, enlaces y límites. También compilan el título más largo de prueba. Esto no certifica accesibilidad completa ni demuestra superioridad estética.</p><nav><a href="qa.json">Controles técnicos</a><a href="probes/summary.json">Pruebas negativas</a><a href="stress/qa.json">Cambio de título</a><a href="../../README.md">Fuentes y reproducción</a></nav></details>
<script>
const select=document.querySelector('#slide'),notes=document.querySelector('#notes');
function update(){const n=Number(select.value);document.querySelectorAll('img[data-code]').forEach(img=>{const c=img.dataset.code;img.src=`previews/${c}/page-${n}-390.png`;img.alt=`Propuesta ${c}, página ${n}`;img.parentElement.href=`previews/${c}/page-${n}.png`});document.querySelector('#prev').disabled=n===1;document.querySelector('#next').disabled=n===9}
select.addEventListener('change',update);document.querySelector('#prev').onclick=()=>{select.value=Number(select.value)-1;update()};document.querySelector('#next').onclick=()=>{select.value=Number(select.value)+1;update()};try{notes.value=localStorage.getItem('educacion-iii-native-notes')||''}catch{}notes.oninput=()=>{try{localStorage.setItem('educacion-iii-native-notes',notes.value)}catch{}};
document.querySelector('#save').onclick=()=>{const url=URL.createObjectURL(new Blob([notes.value],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='educacion-iii-revision.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};update();
</script></html>'''
(O/'index.html').write_text(text)

